package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's {@code membershipNumber}, formatted {@code <customerCode>-M<YY>}
 * where {@code customerCode} is the owner's already-assigned customer code and {@code YY}
 * is the last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
 *
 * <p>Runs after {@link AssignCustomerCode} and {@link BuildOwner} (which assign the
 * {@code customerCode} and default the {@code registrationDate}) and before
 * {@link SaveOwner}, so both inputs are already set on the owner.
 */
public class AssignMembershipNumber {

    public void service(@Val Owner owner) {
        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Household assignment for {@code POST /owners}. When the request opts in via
 * {@code sharesHousehold} true, the new owner joins the household of any existing owner it
 * {@link OwnerHousehold#matches matches}. Both the joining owner and the matched existing
 * owners are assigned the same {@code householdId} — a stable shared identifier (see
 * {@link OwnerHousehold#deriveId}) — so the household is discoverable from any of its members.
 * If a matched owner already carries a {@code householdId}, that value is reused so the
 * identifier stays stable as further members join.
 *
 * <p>Runs within the create transaction (after {@link BuildOwner}/{@link AssignCustomerCode},
 * before {@link SaveOwner}) so the back-filled identifiers on existing owners commit with the
 * new owner. Requests without {@code sharesHousehold} leave {@code householdId} null.
 */
public class AssignHousehold {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        List<Owner> matches = new ArrayList<>();
        String householdId = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (OwnerHousehold.matches(request, existing)) {
                matches.add(existing);
                if (householdId == null && existing.getHouseholdId() != null) {
                    householdId = existing.getHouseholdId();
                }
            }
        }
        if (householdId == null) {
            householdId = OwnerHousehold.deriveId(request);
        }
        owner.setHouseholdId(householdId);
        for (Owner existing : matches) {
            if (!householdId.equals(existing.getHouseholdId())) {
                existing.setHouseholdId(householdId);
                ownerRepository.save(existing);
            }
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Single source of truth for the owner "household" notion used by the {@code POST /owners}
 * pipeline: two owners belong to the same household when they share a last name (compared
 * case-insensitively with collapsed whitespace) and a normalised address (see
 * {@link OwnerAddress#normalize}). Centralised here (rather than inlined in
 * {@link CheckOwnerHouseholdUnique} and {@link AssignHousehold}) so the uniqueness guard and
 * the id assignment cannot silently disagree about who belongs together.
 */
final class OwnerHousehold {

    private OwnerHousehold() {
    }

    /** Whether the create request names the same household as an existing owner. */
    static boolean matches(OwnerFieldsDto request, Owner existing) {
        return normalize(request.getLastName()).equals(normalize(existing.getLastName()))
                && OwnerAddress.normalize(request.getAddress())
                        .equals(OwnerAddress.normalize(existing.getAddress()));
    }

    /**
     * A stable identifier for the household the request names: the first 8 bytes of
     * SHA-256 over the normalised last name and address, upper-cased hex. Deterministic, so
     * every member of the same household derives the same id.
     */
    static String deriveId(OwnerFieldsDto request) {
        String key = normalize(request.getLastName()) + "\n" + OwnerAddress.normalize(request.getAddress());
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 8; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }

    /** The last-name comparison form: trimmed, internal whitespace collapsed, lower-cased. */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}

